/**
 * POST /api/admin-auth/pin — New PIN, from the signed-in admin's own menu (dispatch 38).
 *
 * Request:  `{ currentPin }` — the PIN they hold now (four digits for the
 *           shared PIN, six otherwise)
 * Response: 200 `{ admin, newPin }`, and a new session cookie for this browser
 *
 * Kian's ruling of 2026-10-13 (evening): PINs are generated by Nubnb, never
 * chosen, and "New PIN" in an admin's own menu replaces theirs with another
 * random one, shown once. The current PIN comes first, checked against the
 * admin's own document only (renewOwnPin), so a session alone cannot become
 * a PIN; a wrong one counts against the connection's lock like a sign-in.
 * Every other session the admin holds ends; this browser gets a new token.
 * It is also how a PIN of dispatch 38's first version, or the shared PIN,
 * gives way to a generated one.
 *
 * Refusals, nothing changed: 401 ADMIN_SESSION_INVALID; 401
 * ADMIN_CURRENT_PIN_WRONG; 429 ADMIN_SIGN_IN_LOCKED; 503 when the keys are not
 * set. 502: it may or may not have changed.
 *
 * The body holds a PIN, and the answer the new one: neither is logged. The
 * activity log records that the admin got a new PIN, nothing more.
 */

import { NextRequest } from 'next/server';
import { adminRoute } from '@/app/lib/api/verify-admin';
import { apiError, apiFailure, apiSuccess, noStore } from '@/app/lib/api/safe-response';
import { connectionOf } from '@/app/lib/admins/connection';
import { LOCK_MINUTES, SIGN_IN_PIN_PATTERN } from '@/app/lib/admins/model';
import { lockedResponse, signedInView } from '@/app/lib/admins/responses';
import { RenewPinSchema } from '@/app/lib/admins/schemas';
import { ADMIN_AUTH_NOT_CONFIGURED, getAdminPinKey, getAdminSessionKey } from '@/app/lib/admins/secrets';
import { ADMIN_SESSION_INVALID, createAdminToken, setAdminSessionCookie } from '@/app/lib/admins/session';
import { refuseCrossSite, requireMediaType } from '@/app/lib/cleaners/request-guard';
import { renewOwnPin } from '@/app/lib/firebase/server-admins';

const WRONG = (lastTry: boolean) => ({
  status: 401,
  code: 'ADMIN_CURRENT_PIN_WRONG',
  message: 'That is not your current PIN.',
  hint: lastTry ? `One more wrong PIN locks sign-in from here for ${LOCK_MINUTES} minutes. Nothing was changed.` : 'Nothing was changed.',
});

export const POST = adminRoute(async function POST(request: NextRequest, _context: unknown, { admin }) {
  const crossSite = refuseCrossSite(request);
  if (crossSite) return crossSite;
  const wrongType = requireMediaType(request, 'application/json');
  if (wrongType) return wrongType;
  const sessionKey = getAdminSessionKey();
  const pinKey = getAdminPinKey();
  if (!sessionKey || !pinKey) return noStore(apiFailure(ADMIN_AUTH_NOT_CONFIGURED));

  let body: unknown;
  try {
    body = await request.json();
  } catch {
    return noStore(apiError('Invalid request', 400));
  }
  const parsed = RenewPinSchema.safeParse(body);
  if (!parsed.success) return noStore(apiError('Invalid request', 400));
  const { currentPin } = parsed.data;
  if (!SIGN_IN_PIN_PATTERN.test(currentPin)) return noStore(apiFailure(WRONG(false)));

  const outcome = await renewOwnPin(admin, currentPin, connectionOf(request, pinKey));
  switch (outcome.kind) {
    case 'wrong':
      return noStore(apiFailure(WRONG(outcome.triesLeft === 1)));
    case 'locked':
      return lockedResponse(outcome.lockedUntil, outcome.now);
    case 'session-ended':
      return noStore(apiFailure(ADMIN_SESSION_INVALID));
    case 'not-configured':
      return noStore(apiFailure(ADMIN_AUTH_NOT_CONFIGURED));
    case 'unavailable':
      return noStore(apiFailure({ status: 502, code: 'ADMIN_PIN_CHANGE_UNCONFIRMED', message: 'Could not confirm the new PIN.', hint: 'It may or may not have changed. Sign in again to see which PIN works.' }));
    case 'renewed': {
      // The new PIN travels in this answer only: shown once, stored nowhere.
      const response = noStore(apiSuccess({ admin: signedInView(outcome.admin), newPin: outcome.newPin }));
      setAdminSessionCookie(response, createAdminToken(sessionKey, outcome.admin.id, outcome.admin.sessionEpoch));
      return response;
    }
  }
});
